char* FONTS_GetStringSize(char* str, FONTS_SIZE_t* SizeStruct, FontDef_t* Font) {
	/* Fill settings */
	SizeStruct->Height = Font->height;
	SizeStruct->Length = Font->width * strlen(str);
	
	/* Return pointer */
	return str;
}
